import java.util.*;

class Solution {
  public boolean canMouseWin(String[] grid, int catJump, int mouseJump) {
    int rows = grid.length,
        cols = grid[0].length(),
        cells = rows * cols,
        mouse = -1,
        cat = -1,
        food = -1;
    boolean[] open = new boolean[cells];
    for (int r = 0; r < rows; r++)
      for (int c = 0; c < cols; c++) {
        char ch = grid[r].charAt(c);
        int p = r * cols + c;
        if (ch != '#') open[p] = true;
        if (ch == 'M') mouse = p;
        else if (ch == 'C') cat = p;
        else if (ch == 'F') food = p;
      }
    int states = cells * cells * 2;
    byte[] winner = new byte[states];
    int[] degree = new int[states];
    for (int m = 0; m < cells; m++)
      if (open[m])
        for (int c = 0; c < cells; c++)
          if (open[c] && c != food) {
            degree[index(m, c, 0, cells)] =
                moves(m, mouseJump, true, open, rows, cols, food).size();
            degree[index(m, c, 1, cells)] = moves(c, catJump, false, open, rows, cols, food).size();
          }
    ArrayDeque<Integer> q = new ArrayDeque<>();
    for (int m = 0; m < cells; m++)
      for (int c = 0; c < cells; c++)
        if (open[m] && open[c] && c != food) {
          if (m == food) {
            winner[index(m, c, 0, cells)] = winner[index(m, c, 1, cells)] = 1;
            q.add(index(m, c, 0, cells));
            q.add(index(m, c, 1, cells));
          } else if (m == c) {
            winner[index(m, c, 0, cells)] = winner[index(m, c, 1, cells)] = 2;
            q.add(index(m, c, 0, cells));
            q.add(index(m, c, 1, cells));
          }
        }
    while (!q.isEmpty()) {
      int state = q.poll(),
          turn = state % 2,
          t = state / 2,
          c = t % cells,
          m = t / cells,
          result = winner[state];
      if (turn == 0) {
        for (int pc : moves(c, catJump, false, open, rows, cols, food))
          propagate(index(m, pc, 1, cells), result, winner, degree, q);
      } else {
        for (int pm : moves(m, mouseJump, true, open, rows, cols, food))
          propagate(index(pm, c, 0, cells), result, winner, degree, q);
      }
    }
    return winner[index(mouse, cat, 0, cells)] == 1;
  }

  private int index(int m, int c, int turn, int cells) {
    return (m * cells + c) * 2 + turn;
  }

  private void propagate(
      int state, int result, byte[] winner, int[] degree, ArrayDeque<Integer> q) {
    if (winner[state] != 0) return;
    int turn = state % 2;
    if ((turn == 0 && result == 1) || (turn == 1 && result == 2)) {
      winner[state] = (byte) result;
      q.add(state);
    } else if (--degree[state] == 0) {
      winner[state] = (byte) (turn == 0 ? 2 : 1);
      q.add(state);
    }
  }

  private List<Integer> moves(
      int pos, int jump, boolean mouse, boolean[] open, int rows, int cols, int food) {
    List<Integer> result = new ArrayList<>();
    result.add(pos);
    int r = pos / cols, c = pos % cols;
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (int[] d : dirs)
      for (int step = 1; step <= jump; step++) {
        int nr = r + d[0] * step, nc = c + d[1] * step;
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || !open[nr * cols + nc]) break;
        int next = nr * cols + nc;
        if (mouse || next != food) result.add(next);
      }
    return result;
  }
}
